/**
 * Centralised product data layer.
 *
 * Today: a static catalogue generated by scripts/build-catalog.mjs (Shopify export + samples).
 * Later: swap `loadCatalog()` for a Storefront API fetch (see src/data/shopify.ts). Every
 * component imports from here and never touches the JSON shape directly.
 */
import raw from './catalog.json'
import type { Catalog, Collection, Product, Variant } from './types'

const catalog = raw as Catalog
export const loadCatalog = (): Catalog => catalog
export const products: Product[] = catalog.products
export const collections: Collection[] = catalog.collections
export const currency = catalog.currency

export const byHandle = (h?: string) => products.find((p) => p.handle === h)
export const collectionByHandle = (h?: string) => collections.find((c) => c.handle === h)
export const inCollection = (h: string) => (h === 'all' ? products : products.filter((p) => p.collections.includes(h)))

export const minPrice = (p: Product) => Math.min(...p.variants.map((v) => v.price.amount))
export const maxPrice = (p: Product) => Math.max(...p.variants.map((v) => v.price.amount))
export const onSale = (p: Product) => p.variants.some((v) => v.compareAtPrice && v.compareAtPrice.amount > v.price.amount)
export const money = (n: number, cur = currency) => n.toLocaleString('en-US', { style: 'currency', currency: cur, maximumFractionDigits: n % 1 ? 2 : 0 })
export const fromPrice = (p: Product) => (minPrice(p) === maxPrice(p) ? money(minPrice(p)) : `from ${money(minPrice(p))}`)

export const findVariant = (p: Product, sel: Record<string, string>): Variant =>
  p.variants.find((v) => v.selectedOptions.every((o) => sel[o.name] === o.value)) ?? p.variants[0]
/** First available variant, preferring the metal the photos were shot in so the first view is the real photo. */
export const defaultSelection = (p: Product): Record<string, string> => {
  const inPhotoMetal = (x: Variant) => !p.photoMetal || x.selectedOptions.every((o) => !/metal|colou?r/i.test(o.name) || o.value === p.photoMetal)
  const v = p.variants.find((x) => x.availableForSale && inPhotoMetal(x)) ?? p.variants.find((x) => x.availableForSale) ?? p.variants[0]
  return Object.fromEntries(v.selectedOptions.map((o) => [o.name, o.value]))
}
/** Is this option value purchasable given the other current selections? */
export const valueAvailable = (p: Product, sel: Record<string, string>, name: string, value: string) =>
  p.variants.some((v) => v.availableForSale && v.selectedOptions.every((o) => (o.name === name ? o.value === value : sel[o.name] === o.value)))

export const isMetalOption = (name: string) => /metal|colou?r|gold|plating|finish/i.test(name)
export const metalSwatch = (v: string) => (/rose/i.test(v) ? '#d8a48f' : /white|silver|platinum|steel/i.test(v) ? '#d4d6da' : /black/i.test(v) ? '#2a2a2c' : /two.?tone/i.test(v) ? 'linear-gradient(90deg,#d9b46a 50%,#d4d6da 50%)' : '#d2ad5e')

/** Simple weighted search over title, type, tags, description and option values. */
export function search(q: string, limit = 12): Product[] {
  const words = q.toLowerCase().split(/[^a-z0-9.]+/).filter((w) => w.length > 1).map((w) => (w.length > 3 && w.endsWith('s') ? w.slice(0, -1) : w))
  if (!words.length) return []
  return products
    .map((p) => {
      const hay = [p.title, p.productType, p.tags.join(' '), p.description, p.collections.join(' ').replace(/-/g, ' '), ...p.options.flatMap((o) => o.values)].join(' ').toLowerCase()
      if (!words.every((w) => hay.includes(w))) return null
      return { p, s: words.filter((w) => p.title.toLowerCase().includes(w)).length * 3 + words.filter((w) => p.productType.toLowerCase().includes(w)).length }
    })
    .filter((x): x is { p: Product; s: number } => !!x)
    .sort((a, b) => b.s - a.s).map((x) => x.p).slice(0, limit)
}

export const related = (p: Product, n = 4) => {
  const same = products.filter((x) => x.handle !== p.handle && (x.collections.some((c) => p.collections.includes(c)) || x.productType === p.productType))
  const rest = products.filter((x) => x.handle !== p.handle && !same.includes(x))
  return [...same, ...rest].slice(0, n)
}
export const bestSellers = (n = 8) => [...products].sort((a, b) => (b.tags.includes('best-seller') ? 1 : 0) - (a.tags.includes('best-seller') ? 1 : 0)).slice(0, n)
export const newest = (n = 8) => [...products].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, n)

/**
 * Responsive image props for product photos: an 800px copy for phones and small cards, the 1600px
 * original for large screens. Other media (films, Instagram) pass through unchanged.
 */
export const rs = (src: string, sizes = '(min-width: 68.75em) 25vw, (min-width: 43.75em) 33vw, 72vw') =>
  /\/media\/products\/.+-\d\.webp$/.test(src) ? { src, srcSet: `${src.replace(/\.webp$/, '-800.webp')} 800w, ${src} 1600w`, sizes } : { src }

/**
 * Metal preview: recolours a product photo shot in one metal to show another. Tuned on the sample
 * photography (black satin ground); from yellow or rose the result is close, from white it is a light
 * tint only, so the PDP always says which metal the photo really shows.
 */
type MetalKey = 'yellow' | 'white' | 'rose'
export const metalKey = (v?: string): MetalKey | null => (!v ? null : /rose/i.test(v) ? 'rose' : /white|silver|platinum|steel/i.test(v) ? 'white' : /yellow|gold/i.test(v) ? 'yellow' : null)
const TINT: Record<MetalKey, Partial<Record<MetalKey, string>>> = {
  yellow: { white: 'grayscale(1) brightness(1.12) contrast(1.06)', rose: 'hue-rotate(-24deg) saturate(.85) brightness(1.02)' },
  rose: { yellow: 'hue-rotate(22deg) saturate(1.25)', white: 'grayscale(1) brightness(1.08) contrast(1.05)' },
  white: { yellow: 'sepia(.42) saturate(1.5) hue-rotate(-4deg) brightness(1.03)', rose: 'sepia(.36) saturate(1.25) hue-rotate(-30deg) brightness(1.02)' },
}
export const metalFilter = (photo?: string, chosen?: string) => {
  const a = metalKey(photo), b = metalKey(chosen)
  return a && b && a !== b ? TINT[a][b] ?? 'none' : 'none'
}
/** The selected metal option value on a product, if it has a metal option. */
export const chosenMetal = (p: Product, sel: Record<string, string>) => { const o = p.options.find((x) => isMetalOption(x.name)); return o ? sel[o.name] : undefined }
